        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Question answer could not be updated' })
        }
    }
    const handleSelectChange = (event: SelectChangeEvent) => {
        try {
            if (!event.target.name) throw new Error('Missing structured question id')
